  "body": "# 健康改良川味家庭晚餐\n\n## 菜单概览\n- **前菜**: [菜品名称]\n- **主菜**: [菜品名称]\n- **配菜**: [菜品名称]\n- **饮品**: [饮品名称]\n\n---\n\n### 1. 前菜: [菜品名称]\n- **食材清单**:\n  - [食材1]: [具体用量]\n  - [食材2]: [具体用量]\n  - ...\n- **制作步骤**:\n  1. [步骤一]\n  2. [步骤二]\n  3. ...\n- **营养分析**: [简要说明其核心营养价值，如：低脂高蛋白、富含维生素C等]\n- **估算热量**: [标注总热量及人均热量]\n\n### 2. 主菜: [菜品名称]\n- **食材清单**:\n  - [食材1]: [具体用量]\n  - [食材2]: [具体用量]\n  - ...\n- **制作步骤**:\n  1. [步骤一]\n  2. [步骤二]\n  3. ...\n- **营养分析**: [简要说明其核心营养价值]\n- **估算热量**: [标注总热量及人均热量]\n\n### 3. 配菜: [菜品名称]\n- **食材清单**:\n  - [食材1]: [具体用量]\n  - [食材2]: [具体用量]\n  - ...\n- **制作步骤**:\n  1. [步骤一]\n  2. [步骤二]\n  3. ...\n- **营养分析**: [简要说明其核心营养价值]\n- **估算热量**: [标注总热量及人均热量]\n\n### 4. 饮品: [饮品名称]\n- **食材清单**:\n  - [食材1]: [具体用量]\n  - [食材2]: [具体用量]\n  - ...\n- **制作步骤**:\n  1. [步骤一]\n  2. [步骤二]\n  3. ...\n- **营养分析**: [简要说明其核心营养价值，如：解腻、助消化等]\n- **估算热量**: [标注总热量及人均热量]\n\n---\n\n## 烹饪总览\n- **预计总耗时**: [总时长]\n- **人均总热量**: [计算并汇总上述菜品的人均热量]\n- **准备建议**: [提供一些可以提前准备或同步进行的步骤建议，以优化烹饪流程]\n\n## 示例（用于风格参考）\n以下是一个符合要求的菜品模块示例，请确保你的输出遵循此风格：\n\n### 1. 前菜: 蒜泥青瓜卷\n- **食材清单**:\n  - 青瓜: 2根 (约400克)\n  - 鸡胸肉: 100克\n  - 大蒜: 5瓣\n  - 小米椒: 2个\n  - 生抽: 2汤匙\n  - 醋: 1汤匙\n  - 糖: 半茶匙\n  - 香油: 几滴\n- **制作步骤**:\n  1. 鸡胸肉煮熟撕成细丝；大蒜和小米椒切末。\n  2. 用削皮刀将青瓜刨成长薄片。\n  3. 将鸡丝卷入青瓜片中，码放在盘子里。\n  4. 将蒜末、小米椒、生抽、醋、糖和香油混合成酱汁，淋在青瓜卷上即可。\n- **营养分析**: 清爽开胃，富含维生素和优质蛋白质，脂肪含量极低。\n- **估算热量**: 总计约280大卡，人均约93大卡。",
