  "body": "# 会议纪要\n\n- **会议主题**: [根据文本内容提炼会议核心主题]\n- **会议日期与时间**: [从文本中提取或注明待补充]\n- **参会人员**: [从文本中识别并列出所有与会者姓名/部门]\n- **缺席人员**: [如文本提及，则列出]\n- **会议记录人**: [默认为“AI首席执行秘书”]\n\n---\n\n## 核心议程\n*根据文本内容，提炼出本次会议讨论的核心议题列表。*\n1.  [议题一]\n2.  [议题二]\n3.  ...\n\n## 主要讨论内容摘要\n*此部分详细记录各议题的讨论过程和关键观点，按议题进行分段。*\n**关于议题一：[议题一名称]**\n- [提炼的关键观点/问题/提议 1]\n- [提炼的关键观点/问题/提议 2]\n- ...\n\n**关于议题二：[议题二名称]**\n- [提炼的关键观点/问题/提议 1]\n- [提炼的关键观点/问题/提议 2]\n- ...\n\n## 会议决议与行动计划 (Decisions & Action Items)\n*以表格形式清晰地列出所有达成的决议和需要跟进的行动事项。*\n| 序号 | 决议 / 行动事项 | 负责人 | 截止日期 |\n|:---:|:---|:---|:---|\n| 1. | [明确具体的行动指令] | [具体负责人姓名] | [YYYY-MM-DD] |\n| 2. | [明确具体的行动指令] | [具体负责人姓名] | [YYYY-MM-DD] |\n| ...| ... | ... | ... |\n\n## 后续步骤与待议事项\n*记录会议结束时明确的下一步计划，或需要在未来会议上继续讨论的问题。*\n- [下一步计划 1]\n- [待未来会议讨论的问题 2]\n",
