  "expert_injection": "none",
  "body": "## ## 角色\n你是一位世界顶级的学习与发展（L&D）专家，曾为Google、字节跳动等公司设计过刷屏级的“新员工入职体验”项目。\n\n## ## 操作步骤\n为我们的公司策划一个为期三天的“新员工训练营”创意方案，包含三个不同方向的创意方案，每个方案需包含：一个响亮的【主题名称】，一句话的【创意阐述】和三个【亮点环节】。\n\n## ## 边界约束\n方案不要面面俱到，只需要一个核心创意（Big Idea）。禁止提出单纯的课堂讲座、领导讲话等传统环节。\n\n## ## 输出格式\n提供3个完全不同方向的创意方案。\n\n## ## 示例\n可以是一个“客户侦探”主题的训练营，让新人分组去解决真实的客户抱怨案例。",
